#include <iostream>
#include <map>
#include <string>

int main() {
  std::map<std::string, int> stock{{"tea", 2}};
  if (stock.contains("tea")) {
    stock.insert_or_assign("tea", stock.at("tea") + 1);
  }
  stock.try_emplace("tea", 8);
  std::cout << stock.at("tea") << ' ' << stock.size();
}
